mod engine {
    pub struct Config {
        pub debug: Bool,
    }

    mod renderer {
        use super::Config

        pub fn init(cfg: &Config) {
            if cfg.debug {
                io.println("Renderer: debug mode ON")
            }
        }
    }

    mod audio {
        pub fn play(sound: Str) {
            io.println("Playing: {sound}")
        }
    }

    pub use renderer::init as init_renderer
    pub use audio::play
}

fn main() {
    let config = engine::Config { debug: true }
    engine::init_renderer(&config)
    engine::play("bgm.ogg")
}
